def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((agent_id, opp))

    if not alive:
        bid = min(budget, DAILY_SALARY * 0.35)
        return float(max(0.0, bid))

    cindy = opponents_status.get('Cindy')
    cindy_prev_bid = None
    cindy_urgent = False
    if cindy and cindy.get('alive'):
        prev = cindy.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            cindy_prev_bid = float(prev['bid'])
        cindy_urgent = (cindy.get('hp', 10) <= 3) or (cindy.get('no_water_days', 0) >= 1)

    threatening_bids = []
    urgent_count = 0
    for agent_id, opp in alive:
        if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
            urgent_count += 1
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            threatening_bids.append(float(prev['bid']))

    highest_prev = max(threatening_bids) if threatening_bids else 0.0

    scarcity = (supply <= 17)
    comfortable_supply = (supply >= 22)
    my_urgent = (hp <= 3) or (no_water_days >= 1)
    critical = (hp <= 2) or (no_water_days >= 2)

    if critical:
        base = DAILY_SALARY * 0.96
    elif my_urgent:
        base = DAILY_SALARY * 0.82
    elif scarcity:
        base = DAILY_SALARY * 0.58
    elif comfortable_supply:
        base = DAILY_SALARY * 0.34
    else:
        base = DAILY_SALARY * 0.45

    if cindy_prev_bid is not None:
        if cindy_prev_bid >= 110:
            if not my_urgent:
                base = min(base, DAILY_SALARY * 0.38)
            else:
                base = max(base, DAILY_SALARY * 0.88)
        elif cindy_prev_bid >= 85:
            if scarcity or my_urgent:
                base = max(base, DAILY_SALARY * 0.72)
            else:
                base = min(max(base, cindy_prev_bid * 0.62), DAILY_SALARY * 0.6)
        else:
            base = max(base, min(DAILY_SALARY * 0.68, cindy_prev_bid + 3.0))

    if cindy_urgent and scarcity:
        base = max(base, DAILY_SALARY * 0.78)

    if urgent_count >= 2 and not comfortable_supply:
        base = max(base, DAILY_SALARY * 0.7)

    if day >= 8 and hp >= 6 and budget > DAILY_SALARY * 4:
        base = min(base, DAILY_SALARY * 0.42)

    if day >= 8 and my_urgent:
        base = max(base, DAILY_SALARY * 0.9)

    if budget < DAILY_SALARY * 1.2 and not critical:
        base = min(base, budget * 0.72)

    bid = min(budget, max(0.0, base))
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15
    EPISODE_DAYS = 10

    alive_opponents = [o_status for agent_id, o_status in opponents_status.items() if o_status['alive']]
    num_alive_opponents = len(alive_opponents)

    total_water_needed = WATER_REQ
    for opp in alive_opponents:
        total_water_needed += opp['water_requirement']

    bid = DAILY_SALARY * 0.5

    if my_status['hp'] <= 2 or my_status['no_water_days'] > 0:
        bid = DAILY_SALARY * 0.95
    elif my_status['hp'] <= 4:
        bid = DAILY_SALARY * 0.8

    yesterday_bids = []
    for opp_status in alive_opponents:
        prev = opp_status.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        if highest_prev_bid >= DAILY_SALARY * 0.7:
            bid = max(bid, highest_prev_bid + 5)
        elif highest_prev_bid >= DAILY_SALARY * 0.3:
            bid = max(bid, highest_prev_bid + 2)

    if day_context['supply'] < total_water_needed:
        bid *= 1.1
    elif day_context['supply'] < (WATER_REQ * (num_alive_opponents + 1) * 1.2):
        bid *= 1.05

    if day_context['day'] >= EPISODE_DAYS - 2:
        bid = max(bid, DAILY_SALARY * 0.85)

    alex_status = opponents_status.get('Alex')
    if alex_status and alex_status['alive']:
        alex_prev_trace = alex_status.get('previous_trace', {})
        if alex_prev_trace and alex_prev_trace.get('bid') is not None:
            alex_prev_bid = alex_prev_trace['bid']
            if alex_prev_bid >= DAILY_SALARY * 0.8:
                if my_status['hp'] <= 3:
                    bid = max(bid, alex_prev_bid + 10)
                elif my_status['hp'] > 5 and day_context['supply'] > WATER_REQ * 2:
                    bid = min(bid, alex_prev_bid * 0.9)
                    bid = max(bid, DAILY_SALARY * 0.5)
            elif alex_prev_bid >= DAILY_SALARY * 0.5:
                bid = max(bid, alex_prev_bid + 2)

    if num_alive_opponents == 0:
        bid = DAILY_SALARY * 0.1
        if day_context['supply'] < WATER_REQ and my_status['budget'] > 0:
            bid = max(bid, 1.0)
        elif my_status['budget'] == 0:
            bid = 0.0

    final_bid = min(bid, my_status['budget'])
    final_bid = min(final_bid, DAILY_SALARY * 1.1)

    if final_bid > 0:
        final_bid = max(final_bid, 1.0)
    else:
        final_bid = 0.0

    return final_bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    supply = int(day_context['supply'])  # ensure integer for index
    day = int(day_context['day'])
    hp = int(my_status['hp'])
    budget = float(my_status['budget'])

    alive_opponents = {k: v for k, v in opponents_status.items() if v['alive']}
    if not alive_opponents:
        return min(budget, DAILY_SALARY * 0.4)

    # Collect previous bids from alive opponents
    prev_bids = []
    for opp in alive_opponents.values():
        trace = opp.get('previous_trace', {})
        if trace and trace.get('bid') is not None:
            prev_bids.append(float(trace['bid']))

    # Base bid: moderate fraction of salary, adjusted by supply scarcity
    supply_ratio = supply / 25.0  # normalize between 0.6 and 1.0
    base_bid = DAILY_SALARY * (0.35 + 0.15 * (1 - supply_ratio))

    # Aggressive if HP very low
    if hp <= 2:
        target = max(base_bid, DAILY_SALARY * 0.9)
        if prev_bids:
            max_prev = max(prev_bids)
            target = max(target, max_prev + 1.0)
        return min(budget, target)

    # Standard: look at yesterday's top bid
    if prev_bids:
        max_prev = max(prev_bids)
        # If Cindy's bid extremely high, avoid confrontation
        if max_prev >= DAILY_SALARY * 0.85:
            if hp > 5:
                return min(budget, base_bid * 0.6)
            else:
                return min(budget, max(base_bid, max_prev - 5.0))
        else:
            return min(budget, max(base_bid, max_prev + 2.0))

    # No previous data: use base
    return min(budget, base_bid)
